            aOrbiterF = RotL64((aOrbiterF * 0x8646CA1B16B245D7ULL), 57U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterD) + 0x825C0479BD0E10D0ULL) + aPhaseDOrbiterUpdateSaltD[(((31U - aIndex) + 25U)) & S_SALT1];
