            aOrbiterE = (aWandererA + RotL64(aPrevious, 21U)) + 0xD3BCCFE923EC5045ULL;
            aOrbiterK = ((aWandererJ + RotL64(aCross, 57U)) + 0x87DC12073FB5176FULL) + aPhaseBOrbiterAssignSaltF[((aIndex + 10U)) & S_SALT1];
