            aOrbiterD = ((aWandererH + RotL64(aCross, 12U)) + RotL64(aCarry, 35U)) + 0xE18DA388A6BBDF05ULL;
            aOrbiterG = (((aWandererF + RotL64(aScatter, 47U)) + RotL64(aCarry, 11U)) + 0x99FCC14A2777F5D8ULL) + aPhaseBOrbiterAssignSaltE[((aIndex + 15U)) & S_SALT1];
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x97B3B3A2755CA272ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0x0C07301E4815B876ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x566ECFA9A5B45339ULL), 27U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterI) + 0xD7EC977BC8D22E79ULL) + aPhaseBOrbiterUpdateSaltE[((aIndex + 7U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterK) ^ 0x7C21AB236EBDEDE6ULL;
