            aOrbiterD = ((aOrbiterD + aOrbiterE) + 0x3A81A7063F293A9FULL) + aPhaseBOrbiterUpdateSaltB[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterD) ^ 0x3A45AF930346E375ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x55A897BEF8EA7C7BULL), 43U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterK) + 0xA75486A57E26EB73ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterF) ^ 0xF2E965C0EE75C932ULL;
            aOrbiterG = RotL64((aOrbiterG * 0xE6E193CB1BE85987ULL), 19U);
            //
            aOrbiterG = ((aOrbiterG + aOrbiterC) + 0x5B385C82EFD1FC43ULL) + aPhaseBOrbiterUpdateSaltF[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0x3D820C9E215119C9ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x7C2F12BB07B14B09ULL), 13U);
